window.products.push({"id":637352,"name":"Yankke Candle Red Apple Wreath ScentPlug Refill 2-Pack","category":"homeandappliances","retail price":19.65,"sale price":null,"image":"https://m.media-amazon.com/images/I/719uTqFDV9L._SL1500_.jpg","description":"2-Pack 0.625 ounces each. About Yankee Candle ScentPlug Refills Choose a ScentPlug Refill fragrance that matches your mood, your décor or the season. They offer a clever way to bring a signature fragrance to every room of the house. Great for entryways, bathrooms and even bedrooms, these tiny scent makers deliver for up to four weeks. That's a whole month of welcoming fragrance. . . nice!","images":["https://m.media-amazon.com/images/I/719uTqFDV9L._SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Yankee Candle","source_asin":"B01ALB6CU4","category_path":"Home & Kitchen"},"sku":"BM-637352","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01ALB6CU4","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01ALB6CU4","price_pending":true,"merchant_ready":false});
